/** Public contracts reviewed against Kotlin declarations and their decoders.
 * Keys use catalogue identities; shared text is assigned only to explicit IDs.
 * Native/JVM observations deliberately keep their distinct units and lifetimes. */
type Translation = readonly [string, string]
export const apiContracts: Record<string, Translation> = {}
export const apiContractGuides: Record<string, readonly string[]> = {}
const native = 'native:nimby:'
const jvm = 'jvm:fr.nimby.sdk:'
function add(scope: string, key: string, fr: string, en: string) {
  const id = scope + key
  if (apiContracts[id]) throw new Error(`Duplicate data API contract: ${id}`)
  apiContracts[id] = [fr, en]
}
function type(scope: string, name: string, fr: string, en: string, guide: string) {
  add(scope, `class:${name}`, fr, en)
  apiContractGuides[scope + `class:${name}`] = [guide]
}
function fields(scope: string, owner: string, values: Record<string, Translation>) {
  for (const [name, [fr, en]] of Object.entries(values)) add(scope, `val:${owner}.${name}`, fr, en)
}
function entries(scope: string, owner: string, values: Record<string, Translation>) {
  for (const [name, [fr, en]] of Object.entries(values)) add(scope, `enum-entry:${owner}.${name}`, fr, en)
}
function methods(scope: string, values: Record<string, Translation>) {
  for (const [signature, [fr, en]] of Object.entries(values)) add(scope, `fun:${signature}`, fr, en)
}
const opaque: Translation = ['Valeur opaque à comparer et transmettre telle quelle ; ne pas la découper ni la réutiliser dans une autre partie.', 'Opaque value to compare and pass unchanged; do not decode it or reuse it in another game.']
const captured: Translation = ['Horodatage UTC de l’ordinateur, en millisecondes depuis 1970. Il ne mesure pas le temps simulé.', 'Computer UTC timestamp in milliseconds since 1970. It does not measure simulation time.']
const generation: Translation = ['Génération observée de la partie. Invalider les données dérivées lorsqu’elle change, même si la même sauvegarde est rechargée.', 'Observed game generation. Invalidate derived data when it changes, even when reloading the same save.']
const world: Translation = ['Identité du monde observé, à conserver avec sa génération pour identifier la portée des données.', 'Observed world identity; retain it with its generation to identify the scope of the data.']
const speedFallback: Translation = ['Indique une vitesse de secours du jeu. Ce cas laisse la vitesse mesurée inconnue ; il ne prouve pas un arrêt.', 'Indicates a fallback game speed. Measured speed remains unknown in this case; it does not prove a stop.']
const declaredTags: Translation = ['Tags déclarés directement sur cet objet, sans héritage implicite. null : indisponibles ou non demandés ; liste vide : aucun tag déclaré observé.', 'Tags declared directly on this object, without implicit inheritance. null: unavailable or unrequested; empty list: no observed declared tags.']
const predictedUs: Translation = ['Retard d’arrivée estimé par le jeu, en microsecondes signées ; négatif pour une arrivée prévue en avance. null si inconnu. Ce n’est ni l’âge d’une échéance ni une priorité.', 'Game-estimated arrival delay in signed microseconds; negative means predicted early arrival. null when unknown. Neither a deadline’s age nor a priority.']
const predictedSeconds: Translation = ['Même estimation d’arrivée, convertie de microsecondes en secondes ; conserve le signe et null.', 'The same arrival estimate converted from microseconds to seconds; preserves its sign and null.']
const configured: Translation = ['Profil configuré/acheté du train, demandé explicitement. Indépendant du matériel actuel : ses valeurs ne remplacent pas celles qui manquent dans current.', 'Explicitly requested configured/purchased train profile. Independent of current material: its values do not replace missing current values.']
const current: Translation = ['Caractéristiques de la composition actuelle, si observables et demandées. Ne pas les remplacer par le profil configuré.', 'Characteristics of the current composition, when observable and requested. Do not substitute the configured profile.']
const parentAvailable: Translation = ['true : l’information de parent a été observée, y compris l’absence de parent. false : un parent absent reste inconnu.', 'true: parent information was observed, including no parent. false: an absent parent remains unknown.']
const timetableName: Translation = ['Le SDK expose actuellement l’identité de l’horaire, sans résoudre son nom ; null n’est pas un nom vide.', 'The SDK currently exposes timetable identity without resolving its name; null is not an empty name.']
const trainQueryFields: Record<string, Translation> = {
  includeService: ['Demande l’état et le service des trains. Activé par défaut ; les horaires impliquent aussi cette lecture.', 'Requests train state and service. Enabled by default; timetables also imply this read.'],
  includeLocations: ['Demande les données de localisation et leurs gares/voies. Activé par défaut. Les horaires impliquent aussi ces données ; false ne garantit pas leur absence dans une capture couvrante.', 'Requests location data and related stations/tracks. Enabled by default. Timetables also imply these data; false does not guarantee their absence from a covering snapshot.'],
  includeCharacteristics: ['Demande séparément les caractéristiques configurées et actuelles du matériel. Désactivé par défaut.', 'Requests configured and current material characteristics separately. Disabled by default.'],
  includeTimetables: ['Demande affectations et données d’horaires disponibles ; implique le service ainsi que les voies/gares, même si includeLocations vaut false. N’invente ni nom ni passages futurs.', 'Requests available assignments and timetable data; implies service and track/station data even when includeLocations is false. Does not invent names or future passing times.'],
  includeTags: ['Demande les tags des trains et le catalogue des tags/lignes nécessaire aux jointures ; implique includeLines.', 'Requests train tags and the tag/line catalogue needed for joins; implies includeLines.'],
  includePassengers: ['Demande le nombre d’occupants ; indépendant de la capacité du matériel.', 'Requests occupant count; independent of material capacity.'],
  includeLines: ['Demande le catalogue des lignes, y compris celles sans train affecté. Ne demande pas les tags à lui seul.', 'Requests the line catalogue, including lines without assigned trains. Does not request tags by itself.'],
  includeComposition: ['Demande les véhicules ordonnés et les modèles référencés des compositions configurée et actuelle. Les groupes restent facultatifs.', 'Requests ordered vehicles and referenced models for configured and current compositions. The groups remain optional.'],
}
const characteristicsFields: Record<string, Translation> = {
  maximumSpeedMps: ['Limite du matériel en mètres par seconde, optionnelle ; différente de la vitesse mesurée et de la limite de voie.', 'Optional material speed limit in metres per second; distinct from measured speed and track limit.'],
  maximumSpeedKmh: ['maximumSpeedMps multiplié par 3,6 ; null reste null.', 'maximumSpeedMps multiplied by 3.6; null remains null.'],
  lengthM: ['Longueur du matériel en mètres ; null si non prouvée.', 'Material length in metres; null when not established.'],
  emptyMassKg: ['Masse à vide en kilogrammes ; ne représente pas la masse chargée.', 'Empty mass in kilograms; does not represent loaded mass.'],
  passengerCapacity: ['Capacité en voyageurs de ce profil, optionnelle ; différente des occupants actuellement transportés.', 'Optional passenger capacity of this profile; distinct from current occupants.'],
  carCount: ['Nombre de véhicules de ce profil, optionnel ; ne déduire ni capacité ni longueur de ce nombre seul.', 'Optional vehicle count of this profile; do not infer capacity or length from this count alone.'],
  maximumAccelerationMps2: ['Accélération maximale déclarée, en mètres par seconde carrée ; pas une accélération mesurée.', 'Declared maximum acceleration in metres per second squared; not measured acceleration.'],
  powerW: ['Puissance déclarée en watts, optionnelle ; pas une consommation électrique observée.', 'Optional declared power in watts; not observed electrical consumption.'],
  tractiveForceN: ['Force de traction déclarée en newtons, optionnelle.', 'Optional declared tractive force in newtons.'],
  composition: ['Véhicules dans leur ordre observé. null : inconnus ou non demandés ; liste vide : composition observée vide. Les répétitions d’un modèle sont significatives.', 'Vehicles in observed order. null: unknown or unrequested; empty list: observed empty composition. Repeated models are significant.'],
}
for (const scope of [native, jvm]) {
  type(scope, 'TrainQuery', 'Options d’une lecture de trains. Demander uniquement les groupes utiles ; les options sélectionnent des données, pas un sous-ensemble de trains.', 'Options for a train read. Request only the groups you need; options select data, not a subset of trains.', '/lire/trains-observations')
  fields(scope, 'TrainQuery', trainQueryFields)
  for (const [name, fr, en] of [
    ['TrainId', 'train', 'train'], ['LineId', 'ligne', 'line'], ['StationId', 'gare', 'station'],
    ['TrackId', 'voie', 'track'], ['TimetableId', 'horaire', 'timetable'], ['TagId', 'tag', 'tag'], ['VehicleModelId', 'modèle de véhicule', 'vehicle model'],
  ] as const) {
    type(scope, name, `Identifiant typé de ${fr}, copié du jeu. Son type empêche les jointures entre objets différents ; aucune catégorie métier n’est encodée pour le mod.`, `Typed ${en} identity copied from the game. Its type prevents joins between different objects; it encodes no business category for the mod.`, '/lire/trains-observations')
    fields(scope, name, { value: opaque })
  }
  type(scope, 'TimetableShiftId', 'Identité d’un service dans son horaire. La valeur seule n’est pas unique : comparer le couple timetableId et value.', 'Identity of a shift within its timetable. The value alone is not unique: compare timetableId and value together.', '/lire/horaires-trains')
  fields(scope, 'TimetableShiftId', { timetableId: ['Horaire auquel appartient ce service.', 'Timetable to which this shift belongs.'], value: ['Clé opaque du service, unique seulement au sein de timetableId.', 'Opaque shift key, unique only within timetableId.'] })
  type(scope, 'LineType', 'Classification limitée aux lignes de dépôt et aux autres lignes ; aucune catégorie voyageurs/fret n’est déduite.', 'Classification limited to depot lines and other lines; no passenger/freight category is inferred.', '/lire/lignes-et-tags')
  entries(scope, 'LineType', { Depot: ['Ligne identifiée comme dépôt.', 'Line identified as a depot line.'], Other: ['Ligne observée autre que dépôt ; sa catégorie commerciale n’est pas déterminée.', 'Observed non-depot line; its commercial category is not determined.'] })
  type(scope, 'Timetable', 'Horaire identifié depuis l’affectation d’un train. Ce type ne contient pas un programme complet de passages.', 'Timetable identified from a train assignment. This type does not contain a complete passing schedule.', '/lire/horaires-trains')
  fields(scope, 'Timetable', { id: ['Identité de l’horaire observé.', 'Identity of the observed timetable.'], name: timetableName })
  type(scope, 'Tag', 'Libellé de classement. Comparer l’identifiant ; le nom peut changer. Aucun tag ne déclenche une priorité ou une régulation automatique.', 'Classification label. Compare its identity; its name can change. No tag triggers automatic priority or regulation.', '/lire/lignes-et-tags')
  fields(scope, 'Tag', { id: ['Identité du tag, indépendante de son libellé.', 'Tag identity, independent of its label.'], name: ['Nom observé, éventuellement absent ; ne pas l’utiliser comme clé stable.', 'Observed name, possibly absent; do not use it as a stable key.'] })
  type(scope, 'TrainCharacteristics', 'Caractéristiques copiées d’un profil du matériel, en unités SI. Chaque champ peut être inconnu indépendamment des autres ; ni vitesse instantanée, ni priorité.', 'Copied material-profile characteristics in SI units. Each field can be unknown independently; neither current speed nor priority.', '/lire/materiel')
  fields(scope, 'TrainCharacteristics', characteristicsFields)
  type(scope, 'VehicleModel', 'Modèle référencé par une composition. Le catalogue est limité aux modèles observés ; il ne classe pas les trains en voyageurs ou fret.', 'Model referenced by a composition. The catalogue is limited to observed models; it does not classify trains as passenger or freight.', '/lire/materiel')
  fields(scope, 'VehicleModel', { id: ['Identité du modèle de véhicule.', 'Vehicle-model identity.'], code: ['Code observé du modèle, optionnel.', 'Optional observed model code.'], nameEnglish: ['Nom anglais du catalogue ; ne suit pas automatiquement la langue de l’outil.', 'English catalogue name; does not automatically follow the tool language.'], sourceName: ['Nom de la source du modèle rapporté par le catalogue, optionnel.', 'Optional model-source name reported by the catalogue.'] })
  type(scope, 'TrainVehicle', 'Un véhicule à un emplacement précis d’une composition ; plusieurs véhicules peuvent partager le même modèle.', 'A vehicle at a specific position in a composition; several vehicles may share the same model.', '/lire/materiel')
  fields(scope, 'TrainVehicle', { index: ['Position à partir de zéro dans la composition observée.', 'Zero-based position in the observed composition.'], model: ['Modèle associé à ce véhicule ; ses libellés peuvent rester inconnus.', 'Model associated with this vehicle; its labels can remain unknown.'], modelId: ['Identifiant du modèle, identique à model.id.', 'Model identity, equal to model.id.'] })
  type(scope, 'TrainState', 'État de service observé. null signifie indisponible ; Unknown et Other sont des résultats observés, pas une absence de donnée.', 'Observed service state. null means unavailable; Unknown and Other are observed results, not missing data.', '/lire/trains-observations')
  entries(scope, 'TrainState', {
    Unknown: ['Le jeu rapporte un état indéterminé.', 'The game reports an undetermined state.'], Driving: ['État de conduite rapporté ; ne prouve pas une vitesse strictement positive.', 'Reported driving state; does not prove strictly positive speed.'],
    StationStop: ['Arrêt en gare rapporté.', 'Reported station stop.'], TimedStop: ['Arrêt temporisé rapporté.', 'Reported timed stop.'], Depot: ['État de dépôt rapporté.', 'Reported depot state.'],
    DispatchWait: ['Attente de départ/dispatch rapportée.', 'Reported dispatch wait.'], SignalWait: ['Attente de signal rapportée ; ce champ ne décrit pas à lui seul la règle du signal.', 'Reported signal wait; this field alone does not describe the signal rule.'],
    Mothballed: ['Train remisé hors exploitation selon l’état rapporté.', 'Train mothballed according to the reported state.'], NotPresent: ['Train rapporté non présent ; à distinguer d’un objet absent de la capture.', 'Train reported as not present; distinct from an object missing from the snapshot.'], Other: ['État observé non représenté par une autre valeur connue de cette enum.', 'Observed state not represented by another known enum value.'],
  })
  type(scope, 'TrainAlert', 'Alerte observée du train. null signifie indisponible ; None signifie qu’aucune alerte n’est rapportée. Une alerte n’est pas une priorité.', 'Observed train alert. null means unavailable; None means no reported alert. An alert is not a priority.', '/lire/trains-observations')
  entries(scope, 'TrainAlert', {
    None: ['Aucune alerte rapportée.', 'No reported alert.'], LineClosed: ['Ligne fermée rapportée.', 'Reported closed line.'], NoPath: ['Absence de chemin rapportée.', 'Reported missing path.'], InvalidOrders: ['Ordres invalides rapportés.', 'Reported invalid orders.'], Collision: ['Collision rapportée par le jeu.', 'Collision reported by the game.'], SignalWait: ['Alerte d’attente à un signal.', 'Signal-wait alert.'], ScheduleClosed: ['Horaire fermé rapporté.', 'Reported closed schedule.'], DispatchTracksOccupied: ['Voies de dispatch occupées selon le jeu.', 'Dispatch tracks occupied according to the game.'], NoServices: ['Aucun service disponible selon le jeu.', 'No services available according to the game.'], ServicesAlreadyAssigned: ['Services déjà affectés selon le jeu.', 'Services already assigned according to the game.'], Other: ['Autre code d’alerte observé, non représenté par les valeurs connues.', 'Other observed alert code, not represented by known values.'],
  })
}

