fields(native, 'Line', { id: opaque, lineId: ['Même identité sous le type LineId.', 'The same identity as a LineId.'], name: ['Nom observé de la ligne ; null si indisponible.', 'Observed line name; null when unavailable.'], isDepot: ['true : dépôt ; false : autre type observé ; null : classification inconnue.', 'true: depot; false: another observed type; null: unknown classification.'], type: ['Classification dérivée de isDepot : Depot, Other ou null.', 'Classification derived from isDepot: Depot, Other or null.'], parentLineId: ['Identité du parent ; interpréter null avec parentInformationAvailable.', 'Parent identity; interpret null together with parentInformationAvailable.'], parentInformationAvailable: parentAvailable, declaredTags })
