methods(native, { 'TrainSnapshot.get(Long)': ['Recherche indexée dans les trains copiés ; null si cet identifiant n’y figure pas. Aucune nouvelle observation.', 'Indexed lookup in copied trains; null if the identity is absent. No new observation.'], 'TrainSnapshot.get(TrainId)': ['Même recherche locale avec un identifiant typé ; null si absent de cette capture.', 'The same local lookup with a typed identity; null when absent from this snapshot.'], 'TrainSnapshot.line(LineId)': ['Ligne du catalogue copié ; null si absente, indisponible ou non demandée.', 'Line from the copied catalogue; null when absent, unavailable or unrequested.'], 'TrainSnapshot.tag(TagId)': ['Tag du catalogue copié ; null si absent, indisponible ou non demandé.', 'Tag from the copied catalogue; null when absent, unavailable or unrequested.'], 'TrainSnapshot.tagsForLine(LineId)': ['Réunit les tags déclarés de la ligne et de ses parents, sans doublons. null si un maillon est inconnu, cyclique ou hors limites ; liste vide seulement pour un héritage connu sans tag.', 'Combines declared tags from the line and its parents without duplicates. null if a link is unknown, cyclic or out of bounds; empty list only for known inheritance without tags.'] })
const stopOffsets: Record<string, Translation> = { index: ['Indice d’arrêt à partir de zéro dans le plan de ligne.', 'Zero-based stop index in the line plan.'], arrivalOffsetSeconds: ['Offset d’arrivée en secondes depuis l’origine du plan ; null si inconnu. Pas une date absolue du train.', 'Arrival offset in seconds from the plan origin; null when unknown. Not an absolute train date.'], departureOffsetSeconds: ['Offset de départ en secondes depuis l’origine du plan ; null si inconnu.', 'Departure offset in seconds from the plan origin; null when unknown.'], plannedDwellSeconds: ['departureOffsetSeconds moins arrivalOffsetSeconds, en secondes ; null si un offset manque.', 'departureOffsetSeconds minus arrivalOffsetSeconds, in seconds; null if either offset is missing.'] }
type(native, 'Stop', 'Arrêt ou waypoint du plan de ligne. Peut être hors gare ; les offsets restent relatifs au plan.', 'Stop or waypoint in a line plan. May be outside a station; offsets remain relative to the plan.', '/lire/horaires-trains')
fields(native, 'Stop', { ...stopOffsets, trackId: opaque, track: ['Identité typée de la voie de l’arrêt.', 'Typed identity of the stop track.'], station: ['Gare jointe, si disponible ; un waypoint peut être hors gare.', 'Joined station, when available; a waypoint can be outside stations.'] })
type(native, 'LinePlan', 'Plan complet de la ligne associée au train dans cette capture, obtenu par ToolContext.linePlan. Peut contenir des arrêts hors de la course partielle du train.', 'Complete plan of the line associated with the train in this snapshot, obtained from ToolContext.linePlan. May contain stops outside the train’s partial run.', '/lire/horaires-trains')
fields(native, 'LinePlan', { trainId: opaque, train: ['Identité typée du train qui a servi à demander ce plan.', 'Typed identity of the train used to request this plan.'], line: ['Ligne observée associée au train.', 'Observed line associated with the train.'], stops: ['Arrêts du plan complet, dans leur ordre ; ne pas les convertir directement en prochains passages du train.', 'Stops in the full plan, in order; do not convert them directly into the train’s next passing times.'], worldId: world, generation, capturedAtMillis: captured })
for (const [alias, target] of [['TrainObservation', 'Train'], ['TrainLine', 'Line'], ['TrainStation', 'Station'], ['TrainLineStop', 'Stop'], ['TrainLinePlan', 'LinePlan']]) {
  add(native, `typealias:${alias}`, `Autre nom du type ${target}, avec les mêmes propriétés et contrats ; aucune copie ou conversion supplémentaire.`, `Another name for ${target}, with the same properties and contracts; no additional copy or conversion.`)
  apiContractGuides[native + `typealias:${alias}`] = ['/lire/trains-observations']
}

// JVM: start with Game's grouped operations; keep detailed APIs discoverable.
add(jvm, 'object:Nimby', 'Point d’entrée d’une application JVM : découvrir les jeux puis ouvrir explicitement une connexion. Un mod Native utilise le contexte fourni par le SDK.', 'JVM application entry point: discover games, then explicitly open a connection. A Native mod uses its SDK-provided context.')
apiContractGuides[jvm + 'object:Nimby'] = ['/lire/connexion']
type(jvm, 'Game', 'Connexion possédée par l’application, regroupée par usage. Utiliser use pour la fermer ; les observations copiées restent lisibles après fermeture. Ne pas construire ce type directement.', 'Application-owned connection grouped by purpose. Use use to close it; copied observations remain readable after closing. Do not construct this type directly.', '/lire/connexion')
fields(jvm, 'Game', { advanced: ['Client détaillé de cette même connexion ; ne pas le fermer séparément.', 'Detailed client for this same connection; do not close it separately.'], trains: ['Lectures ciblées et requêtes de trains.', 'Targeted reads and train queries.'], clock: ['Lecture et changement explicite de la date du jeu.', 'Game-clock reads and explicit date changes.'], signals: ['Essais visuels temporaires de textures de signaux.', 'Temporary visual tests of signal textures.'], mods: ['Statut et sessions temporaires de contrôle des mods chargés.', 'Status and temporary control sessions for loaded mods.'], construction: ['Préparation, création, suivi et annulation de séries expérimentales de signaux.', 'Preparation, creation, tracking and undo of experimental signal batches.'] })
for (const [name, fr, en, guide] of [
  ['Trains', 'Accès aux lectures de trains de cette connexion.', 'Access to train reads on this connection.', '/lire/trains-observations'],
  ['Clock', 'Accès à l’horloge du jeu de cette connexion.', 'Access to the game clock on this connection.', '/lire/horloge'],
  ['Signals', 'Actions d’affichage uniquement ; ne modifient pas les permissions de mouvement.', 'Display actions only; do not change movement permissions.', '/lire/recettes'],
  ['Mods', 'Contrôle explicite des mods présents dans la partie connectée.', 'Explicit control of mods present in the connected game.', '/lire/recettes'],
  ['Construction', 'Construction expérimentale par tickets ; chaque écriture doit être confirmée et suivie.', 'Experimental ticket-based construction; every write must be confirmed and tracked.', '/lire/construction'],
] as const) type(jvm, `Game.${name}`, `${fr} Obtenir cet objet depuis Game.`, `${en} Obtain this object from Game.`, guide)
const targetedRead: Translation = ['Lit uniquement le train demandé : position, vitesse mesurée et paramètres de conduite. null si absent ou instable ; les autres échecs lèvent une exception. Le résultat copié reste utilisable après fermeture.', 'Reads only the requested train: position, measured speed and driving parameters. null if absent or unstable; other failures throw. The copied result remains usable after closing.']
const fullCapture: Translation = ['Capture les tables du réseau et les observations usuelles. Un train sélectionné ajoute son chemin et son plan de ligne ; il ne filtre pas la liste des trains. Les tables sont copiées sans garantir un tick atomique.', 'Captures network tables and ordinary observations. A selected train adds its path and line plan; it does not filter the train list. Tables are copied without guaranteeing an atomic tick.']
const trainCapture: Translation = ['Capture spécialisée selon TrainQuery, sans topologie complète, signaux, occupations ni réservations. selectedTrain demande en plus son plan et les données de service/horaires ; la liste des trains reste un lot.', 'Specialised TrainQuery capture without full topology, signals, occupations or reservations. selectedTrain additionally requests its plan and service/timetable data; the train list remains a batch.']
const clockRead: Translation = ['Lit l’horloge du jeu sans demander les grandes tables de la carte avec le SDK courant. null si indisponible. Réutiliser snapshot.clock lorsqu’une capture existe déjà.', 'Reads the game clock without requesting large map tables with the current SDK. null when unavailable. Reuse snapshot.clock when a snapshot already exists.']
const clockSet: Translation = ['Change explicitement la date UTC, en secondes entières. Conserve la fraction de seconde. recalculateTrains demande aussi le recalcul des trains, avec interventions possibles. En cas d’échec, relire avant toute nouvelle écriture.', 'Explicitly changes the UTC date in whole seconds. Preserves the subsecond fraction. recalculateTrains also requests train recalculation, with possible interventions. On failure, read again before any new write.']
const textureShow: Translation = ['Affiche l’image déclarée du catalogue pendant 1 000 à 60 000 ms. Identité de signal réelle et chemins non vides requis. Modifie l’apparence seule, jamais les règles ni permissions.', 'Displays the declared catalogue image for 1,000 to 60,000 ms. Requires a real signal identity and nonempty paths. Changes appearance only, never rules or permissions.']
const textureRestore: Translation = ['Retire le remplacement visuel temporaire demandé pour ce signal ; ne réécrit aucune règle du mod.', 'Removes the requested temporary visual override for this signal; does not rewrite mod rules.']
const constructionPrepare: Translation = ['Prépare une série à partir d’un signal source observé et retourne son ticket/état. N’ajoute pas de signal. Revalider le plan confirmé après préparation et avant création.', 'Prepares a batch from an observed source signal and returns its ticket/state. Adds no signal. Revalidate the confirmed plan after preparation and before creation.']
const constructionCreate: Translation = ['Envoie une création unique avec un ticket préparé et 1 à 64 positions distinctes. Fractions strictement entre 0 et 1, sens -1 ou 1. Conserver le ticket et consulter poll après PENDING ou réponse incertaine ; ne pas répéter create.', 'Sends one creation with a prepared ticket and 1 to 64 distinct positions. Fractions strictly between 0 and 1, directions -1 or 1. Keep the ticket and poll after PENDING or an uncertain response; do not repeat create.']
const constructionPoll: Translation = ['Relit l’état du ticket existant sans répéter sa création ou son annulation. Utiliser un ticket non nul de la même partie/session d’édition.', 'Reads the existing ticket state without repeating creation or undo. Use a nonzero ticket from the same game/editing session.']
const constructionUndo: Translation = ['Demande une seule annulation de la série. Peut être refusée si une autre commande a remplacé la dernière opération annulable. Vérifier état et canUndo ; suivre une réponse incertaine avec poll.', 'Requests one batch undo. May be refused if another command replaced the latest undoable operation. Check state and canUndo; follow an uncertain response with poll.']
const controlAcquire: Translation = ['Acquiert un bail explicite de 1 000 à 60 000 ms auprès d’un mod ayant observé la partie. Fermer avec use ; renouvellement et reprises ne sont jamais automatiques.', 'Acquires an explicit 1,000 to 60,000 ms lease from a mod that has observed the game. Close with use; renewal and retries are never automatic.']
const closeConnection: Translation = ['Ferme cette connexion et libère ses ressources. Les copies Kotlin déjà retournées restent valables comme anciennes observations ; aucun nouvel appel sur cette connexion.', 'Closes this connection and releases its resources. Previously returned Kotlin copies remain valid as old observations; do not make further calls on this connection.']
methods(jvm, {
  'Nimby.runningGames()': ['Liste les processus de jeu visibles ; ne choisit aucun jeu et ne garantit pas qu’une connexion réussira.', 'Lists visible game processes; selects none and does not guarantee a connection will succeed.'],
  'Nimby.connect(Path,Int?)': ['Ouvre le SDK indiqué pour le PID choisi. Sans PID, exige exactement un jeu visible. Retourne Game à fermer avec use ; aucune mutation automatique.', 'Opens the specified SDK for the chosen PID. Without a PID, requires exactly one visible game. Returns a Game to close with use; no automatic mutation.'],
  'Game.snapshot(Long?)': fullCapture, 'Game.close()': closeConnection,
  'Game.Trains.read(Long)': targetedRead, 'Game.Trains.read(TrainId)': targetedRead,
  'Game.Trains.snapshot(TrainId?,TrainQuery)': trainCapture,
  'Game.Clock.read()': clockRead, 'Game.Clock.set(Instant,Boolean)': clockSet,
  'Game.Signals.showTexture(Long,String,String,Int)': textureShow, 'Game.Signals.restoreTexture(Long)': textureRestore,
  'Game.Mods.status(String)': ['Interroge une fois le mod chargé dans cette partie. Les compteurs décrivent des forçages temporaires, pas tous les signaux gérés. Une exception n’est pas une preuve d’absence du mod.', 'Queries the mod loaded in this game once. Counts describe temporary overrides, not all managed signals. An exception is not proof the mod is absent.'],
  'Game.Mods.control(String,Int)': controlAcquire,
  'Game.Construction.prepare(Long)': constructionPrepare, 'Game.Construction.create(Long,Long,List<Position>)': constructionCreate,
  'Game.Construction.poll(Long)': constructionPoll, 'Game.Construction.undo(Long)': constructionUndo,
})
type(jvm, 'NimbyClient', 'Client détaillé possédant une connexion ; préférer Game pour les usages courants. Les opérations de cette connexion sont sérialisées. Ouvrir via open et fermer avec use ; ne pas construire directement.', 'Detailed connection-owning client; prefer Game for common uses. Operations on this connection are serialized. Open through open and close with use; do not construct directly.', '/lire/connexion')
methods(jvm, {
  'NimbyClient.Companion.open(Path,Int)': ['Ouvre la bibliothèque SDK donnée pour un PID strictement positif et vérifie sa compatibilité. Ferme les ressources d’ouverture si la connexion échoue.', 'Opens the given SDK library for a strictly positive PID and checks compatibility. Releases opening resources if connection fails.'],
  'NimbyClient.readTrain(Long)': targetedRead, 'NimbyClient.prepareConstruction(Long)': constructionPrepare,
  'NimbyClient.createSignals(Long,Long,List<Position>)': constructionCreate, 'NimbyClient.undoConstruction(Long)': constructionUndo,
  'NimbyClient.pollConstruction(Long)': constructionPoll, 'NimbyClient.readSimulationClock()': clockRead,
  'NimbyClient.capture(Long?)': fullCapture, 'NimbyClient.captureTrainData(Long?,TrainQuery)': trainCapture,
  'NimbyClient.setSimulationDateTime(java.time.Instant,Boolean)': clockSet,
  'NimbyClient.showSignalTextureFor(Long,String,String,Int)': textureShow, 'NimbyClient.restoreSignalTexture(Long)': textureRestore,
  'NimbyClient.modControl(String,ControlRequest)': ['Envoie exactement une demande au mod nommé dans la partie connectée. Préférer Game.mods et ModControlSession qui portent l’identité du bail. Inspecter l’état après un échec avant de choisir une nouvelle mutation.', 'Sends exactly one request to the named mod in the connected game. Prefer Game.mods and ModControlSession, which carry lease identity. Inspect state after failure before choosing a new mutation.'],
  'NimbyClient.acquireModControl(String,Int)': controlAcquire, 'NimbyClient.close()': closeConnection,
})
type(jvm, 'Train', 'Observation de base d’un train dans une capture JVM. Enrichir par snapshot.train(trainId) pour joindre le service, les lieux et les métadonnées de cette même capture.', 'Basic train observation in a JVM snapshot. Use snapshot.train(trainId) to join service, locations and metadata from that same snapshot.', '/lire/trains-observations')
