fields(jvm, 'Track', { id: opaque, trackId: ['Même identité sous le type TrackId.', 'The same identity as a TrackId.'], stationId: ['Gare associée observée, si disponible.', 'Observed associated station, when available.'], station: ['stationId sous forme typée ; null si aucun identifiant disponible.', 'stationId in typed form; null if no identity is available.'], speedLimitKmh: ['Limite de vitesse de la voie en km/h, distincte de la limite du matériel.', 'Track speed limit in km/h, distinct from the material limit.'] })
