methods(jvm, { 'SimulationClock.toInstant()': ['Additionne l’origine et les ticks, en conservant les centièmes. Rejette les ticks négatifs et les dates hors plage ; aucune lecture du jeu.', 'Adds origin and ticks while preserving hundredths. Rejects negative ticks and out-of-range dates; no game read.'] })
type(jvm, 'SimulationTimeChange', 'Résultat d’un changement explicite de date. Contient l’horloge retournée et le nombre d’interventions lors du recalcul demandé.', 'Result of an explicit date change. Contains the returned clock and intervention count for the requested recalculation.', '/lire/horloge')
fields(jvm, 'SimulationTimeChange', { clock: ['Horloge retournée après la commande ; relire plus tard pour un nouvel état.', 'Clock returned after the command; read again later for new state.'], interventions: ['Nombre d’interventions du recalcul ; zéro lorsqu’aucun recalcul n’a été demandé.', 'Recalculation intervention count; zero when no recalculation was requested.'] })

type(jvm, 'Observation', 'Ensemble de valeurs copiées, conservable après fermeture. Son contenu dépend du mode de capture et des groupes demandés. Les jointures locales n’actualisent rien ; une capture ne garantit pas un tick atomique.', 'Set of copied values, retainable after closing. Contents depend on capture mode and requested groups. Local joins refresh nothing; a snapshot does not guarantee an atomic tick.', '/lire/trains-observations')
fields(jvm, 'Observation', {
  capturedAtMillis: captured, processId: ['PID du jeu source de cette capture ; choisir explicitement la partie lors de la connexion.', 'PID of the game supplying this snapshot; explicitly choose the game when connecting.'], gameHash: ['Empreinte du binaire du jeu observé, utile dans un diagnostic de compatibilité ; pas une identité de sauvegarde.', 'Observed game-binary fingerprint, useful for compatibility diagnostics; not a save identity.'],
  trains: ['Observations de base des trains du lot ; selectedTrain ne filtre pas cette liste.', 'Basic observations of trains in the batch; selectedTrain does not filter this list.'], tracks: ['Voies demandées par le mode de capture. Une requête spécialisée sans lieux peut laisser cette liste vide.', 'Tracks requested by capture mode. A specialised query without locations can leave this list empty.'], stations: ['Gares demandées par le mode de capture ; liste vide ne prouve pas un monde sans gares.', 'Stations requested by capture mode; an empty list does not prove a station-free world.'], nodes: ['Graphe observé de la capture complète ; vide dans la capture spécialisée de trains et éventuellement si indisponible.', 'Observed full-capture graph; empty in specialised train captures and possibly when unavailable.'], junctions: ['Raccords observés de la capture complète ; vide dans la capture spécialisée, sans preuve d’absence d’aiguilles.', 'Observed full-capture attachments; empty in specialised captures without proving there are no junctions.'], signals: ['Signaux observés de la capture complète ; la capture spécialisée de trains ne les demande pas.', 'Observed full-capture signals; specialised train captures do not request them.'],
  services: ['Services demandés et observables ; une liste vide peut aussi résulter d’un groupe non demandé ou indisponible.', 'Requested, observable services; an empty list can also result from an unrequested or unavailable group.'], details: ['Affectations/occupants selon les options de lecture ; interpréter chaque propriété facultative séparément.', 'Assignments/occupants according to read options; interpret each optional property separately.'], platforms: ['Quais de la capture complète, si observables ; non demandés dans la capture spécialisée.', 'Full-capture platforms when observable; not requested in specialised captures.'], reservations: ['Intervalles de réservation, si observables ; null dans une capture spécialisée. Une réservation n’est pas une occupation.', 'Reservation intervals when observable; null in a specialised capture. A reservation is not an occupation.'], occupations: ['Intervalles d’occupation, si observables ; null dans une capture spécialisée. Une table inconnue ne prouve pas une voie libre.', 'Occupation intervals when observable; null in a specialised capture. An unknown table does not prove a clear track.'], selectedPath: ['Chemin du train sélectionné dans une capture complète ; null si non demandé ou indisponible. Pas une permission de passage.', 'Selected train path in a full capture; null when unrequested or unavailable. Not a passage permission.'], lineStops: ['Plan de ligne demandé pour selectedTrain ; null si non demandé ou indisponible. Peut dépasser sa course partielle.', 'Line plan requested for selectedTrain; null when unrequested or unavailable. May extend beyond its partial run.'], clock: ['Horloge simulée copiée avec la capture, si disponible.', 'Simulation clock copied with the snapshot, when available.'], trackMetrics: ['Longueurs observées des voies de la capture complète ; null si non disponibles ou non demandées. Une ligne manquante reste inconnue.', 'Observed full-capture track lengths; null when unavailable or unrequested. A missing row remains unknown.'], lines: ['Catalogue des lignes demandé explicitement ; null si non demandé ou indisponible.', 'Explicitly requested line catalogue; null when unrequested or unavailable.'], tags: ['Catalogue des tags demandé explicitement ; null si non demandé ou indisponible.', 'Explicitly requested tag catalogue; null when unrequested or unavailable.'], trainMetadata: ['Métadonnées enrichies des trains selon TrainQuery ; null hors de cette capture ou si indisponibles.', 'Rich train metadata according to TrainQuery; null outside this capture or when unavailable.'], vehicleModels: ['Modèles référencés par les compositions demandées ; null si non demandés ou indisponibles.', 'Models referenced by requested compositions; null when unrequested or unavailable.'],
})
for (const [name, parameter, fr, en] of [
  ['train', 'Long', 'fiche jointe du train', 'joined train record'], ['train', 'TrainId', 'fiche jointe du train', 'joined train record'],
  ['service', 'Long', 'service du train', 'train service'], ['service', 'TrainId', 'service du train', 'train service'],
  ['details', 'Long', 'fiche d’affectation/occupants du train', 'train assignment/occupant details'], ['details', 'TrainId', 'fiche d’affectation/occupants du train', 'train assignment/occupant details'],
  ['station', 'Long', 'gare', 'station'], ['station', 'StationId', 'gare', 'station'], ['track', 'Long', 'voie', 'track'], ['track', 'TrackId', 'voie', 'track'],
  ['platform', 'Long', 'information de quai pour cette voie', 'platform information for this track'], ['platform', 'TrackId', 'information de quai pour cette voie', 'platform information for this track'],
  ['line', 'LineId', 'ligne du catalogue', 'catalogue line'], ['tag', 'TagId', 'tag du catalogue', 'catalogue tag'], ['metadata', 'TrainId', 'métadonnée enrichie du train', 'rich train metadata'],
]) methods(jvm, { [`Observation.${name}(${parameter})`]: [`Recherche indexée de ${fr} dans cette capture uniquement. null si aucune donnée correspondante ; aucune nouvelle lecture du jeu.`, `Indexed lookup of ${en} in this snapshot only. null if no matching data exists; no new game read.`] })
methods(jvm, { 'Observation.tagsForLine(LineId)': ['Réunit les tags déclarés de la ligne et de ses parents, sans doublons. null si une ligne, un parent ou ses tags sont inconnus, si un cycle apparaît ou si les limites sont dépassées. Ne produit aucune priorité.', 'Combines declared tags of the line and its parents without duplicates. null if a line, parent or tags are unknown, a cycle occurs, or limits are exceeded. Produces no priority.'] })
add(jvm, 'interface:ObservationClient', 'Contrat d’une source d’observations fermable. Utile pour injecter une source contrôlée dans les tests d’une application ; NimbyClient est l’implémentation reliée au jeu.', 'Closeable observation-source contract. Useful for injecting a controlled source into application tests; NimbyClient is the game-connected implementation.')
methods(jvm, { 'ObservationClient.capture(Long?)': fullCapture })
type(jvm, 'GameProcess', 'Processus de jeu découvert. La découverte ne prouve ni qu’une partie est chargée ni que le SDK est compatible.', 'Discovered game process. Discovery proves neither a loaded game nor SDK compatibility.', '/lire/connexion')
fields(jvm, 'GameProcess', { pid: ['Identifiant de processus à passer explicitement à connect.', 'Process identity to pass explicitly to connect.'], executable: ['Chemin de l’exécutable rapporté par le système.', 'Executable path reported by the system.'] })
add(jvm, 'object:GameProcesses', 'Découverte de processus visibles de NIMBY Rails. Préférer Nimby.runningGames au point d’entrée de l’application.', 'Discovery of visible NIMBY Rails processes. Prefer Nimby.runningGames at the application entry point.')
methods(jvm, { 'GameProcesses.discover()': ['Liste les exécutables de jeu reconnus parmi les processus visibles. Retourne une liste vide si aucun n’est visible ; ne sélectionne ni n’ouvre une connexion.', 'Lists recognised game executables among visible processes. Returns an empty list when none is visible; neither selects nor opens a connection.'] })
type(jvm, 'SdkException', 'Échec d’une opération SDK. Conserver message et statut pour le diagnostic ; distinguer d’un résultat optionnel null. Ne pas relancer automatiquement une écriture après exception.', 'SDK operation failure. Retain message and status for diagnostics; distinguish it from an optional null result. Do not automatically repeat a write after an exception.', '/lire/connexion')
fields(jvm, 'SdkException', { status: ['Code du refus : notamment 2 accès impossible, 7 jeu non pris en charge, 8 donnée indisponible, 11 jeu fermé. Conserver les autres codes sans inventer leur signification.', 'Failure code: notably 2 inaccessible process/file, 7 unsupported game, 8 unavailable data, 11 closed game. Retain other codes without inventing their meaning.'] })
type(jvm, 'Line', 'Ligne du catalogue enrichi. Les informations de parent et de tags sont indépendantes du nom ; aucune catégorie commerciale n’est déduite.', 'Line in the rich catalogue. Parent and tag information is independent of its name; no commercial category is inferred.', '/lire/lignes-et-tags')
fields(jvm, 'Line', { id: ['Identité typée de la ligne.', 'Typed line identity.'], name: ['Nom observé, optionnel ; pas une clé de jointure.', 'Optional observed name; not a join key.'], type: ['Depot ou Other quand la classification est connue ; null sinon.', 'Depot or Other when classification is known; null otherwise.'], parentId: ['Identité du parent ; lire parentInformationAvailable avant d’interpréter null.', 'Parent identity; check parentInformationAvailable before interpreting null.'], parentInformationAvailable: parentAvailable, declaredTags })
