fields(jvm, 'TrainRecord', { train: ['Observation de base du train.', 'Basic train observation.'], service: ['Service joint par identité de train, si disponible.', 'Service joined by train identity, when available.'], details: ['Affectation/occupants joints par identité de train, si disponibles.', 'Assignment/occupants joined by train identity, when available.'], positionStation: ['Gare de la voie de position géométrique, si résolue.', 'Station of the geometric position track, when resolved.'], locationStation: ['Gare du lieu de service, si résolue ; peut différer de positionStation.', 'Service-location station when resolved; may differ from positionStation.'], stopStation: ['Gare de l’arrêt ciblé, si résolue ; pas nécessairement la position actuelle.', 'Target-stop station when resolved; not necessarily current position.'], metadata: ['Métadonnées enrichies du même train, si demandées et disponibles.', 'Rich metadata for the same train, when requested and available.'], line: ['Ligne du service jointe dans le catalogue demandé.', 'Service line joined from the requested catalogue.'] })
