type(jvm, 'DrivingObservation', 'Résultat d’une lecture ciblée de conduite. Les profils acheté et actuel sont indépendants ; l’intervalle de temps simulé encadre la lecture, sans garantir un tick atomique.', 'Result of a targeted driving read. Purchased and current profiles are independent; the simulation-time interval bounds the read without guaranteeing an atomic tick.', '/lire/trains')
fields(jvm, 'DrivingObservation', { trainId: opaque, sessionGeneration: ['Génération locale à cette connexion ; réinitialiser l’état dérivé après changement et après toute reconnexion.', 'Generation local to this connection; reset derived state after changes and after every reconnection.'], capturedAtMillis: captured, elapsedBeginMillis: ['Temps simulé écoulé au début de la lecture, en millisecondes.', 'Elapsed simulation time at read start, in milliseconds.'], elapsedEndMillis: ['Temps simulé écoulé à la fin de la lecture, en millisecondes.', 'Elapsed simulation time at read end, in milliseconds.'], purchasedDynamics: ['Paramètres du profil acheté/configuré, si disponibles ; ne remplacent pas currentDynamics.', 'Purchased/configured profile parameters when available; do not substitute for currentDynamics.'], currentDynamics: ['Paramètres du profil actuel, si disponibles ; indépendants du profil acheté.', 'Current-profile parameters when available; independent of the purchased profile.'], position: ['Position ciblée observée ; null si inconnue.', 'Observed targeted position; null when unknown.'], speedMps: ['Vitesse mesurée en mètres par seconde ; null si inconnue ou de secours.', 'Measured speed in metres per second; null when unknown or fallback.'], speedDefaulted: speedFallback, motionAvailable: ['Indique si les données de mouvement sont disponibles ; ne remplace pas les disponibilités propres de position et vitesse.', 'Indicates whether motion data is available; does not replace position and speed’s individual availability.'] })
