methods(jvm, { 'TrackMetric.offsetM(Double)': ['Convertit une fraction finie entre 0 et 1 en mètres depuis l’origine de la voie ; argument invalide rejeté.', 'Converts a finite fraction between 0 and 1 to metres from track origin; rejects invalid input.'], 'TrackMetric.fraction(Double)': ['Convertit une distance finie entre 0 et lengthM en fraction ; ne renverse pas le sens.', 'Converts a finite distance between 0 and lengthM to a fraction; does not reverse direction.'], 'TrackMetric.distanceM(Double,Double)': ['Distance absolue en mètres entre deux fractions valides sur cette même voie ; pas une distance d’itinéraire.', 'Absolute distance in metres between two valid fractions on this same track; not a route distance.'], 'TrackMetric.positionAtMetres(Double,TrackDirection)': ['Construit une Position à la distance donnée depuis l’origine, avec le sens choisi. Les limites de construction restent à vérifier séparément.', 'Builds a Position at the given distance from origin with the chosen direction. Construction constraints still require separate checks.'] })
