methods(jvm, { 'DiagnosticLog.Companion.defaultRoot()': ['Utilise NRF_LOG_DIR si renseigné ; sinon NimbyRailsFrance/logs sous LOCALAPPDATA, ou le dossier utilisateur si cette variable manque.', 'Uses NRF_LOG_DIR when set; otherwise NimbyRailsFrance/logs under LOCALAPPDATA, or the user directory when that variable is missing.'], 'DiagnosticLog.Companion.forComponent(String)': ['Réutilise le journal du nom donné dans cette application, pour partager le regroupement des répétitions.', 'Reuses the named log in this application so repeated-message coalescing is shared.'], 'DiagnosticLog.write(String,Throwable?,String)': ['Écrit un événement et éventuellement une exception ; regroupe les répétitions identiques pendant 30 secondes. Ferme le fichier après écriture ; une erreur d’écriture est rapportée sur stderr.', 'Writes an event and optionally an exception; coalesces identical repetitions for 30 seconds. Closes the file after writing; write failure is reported to stderr.'], 'DiagnosticLog.startApplication(String)': ['À installer une seule fois au point d’entrée de votre application. Journalise version, erreurs JVM non interceptées et arrêt ; conserve le gestionnaire précédent. N’intercepte pas tous les crashs natifs.', 'Install once at your application entry point. Logs version, uncaught JVM errors and shutdown; preserves the previous handler. Does not intercept every native crash.'] })

// Member links inherit only their explicitly assigned public owner's guide.
for (const id of Object.keys(apiContracts)) {
  if (apiContractGuides[id]) continue
  const prefix = id.startsWith(native) ? native : jvm
  const key = id.slice(prefix.length)
  const qualified = key.slice(key.indexOf(':') + 1).replace(/\(.*/, '')
  const parts = qualified.split('.')
  while (parts.length > 1) {
    parts.pop()
    const guide = apiContractGuides[prefix + 'class:' + parts.join('.')]
    if (guide) { apiContractGuides[id] = guide; break }
  }
}
